"use client";

import React, { useState, useMemo } from "react";
import {
    FileText, UploadCloud, Download, Trash2, Eye,
    Search, Clock, CheckCircle2, AlertCircle, Plus,
    MoreVertical, Info, ShieldCheck, History
} from "lucide-react";
import Badge from "@/components/ui/badge/Badge";
import PageBreadcrumb from "@/components/common/PageBreadCrumb";

type DocStatus = "Verified" | "Pending" | "Rejected" | "Expiring Soon";

interface DocumentItem {
    id: string;
    name: string;
    category: "Identity" | "Education" | "Company" | "Tax";
    size: string;
    uploadDate: string;
    status: DocStatus;
    expiryDate?: string;
    version: string;
}

const initialDocs: DocumentItem[] = [
    { id: "1", name: "Aadhar_Card.pdf", category: "Identity", size: "1.2 MB", uploadDate: "12 Jan 2026", status: "Verified", version: "v1.0" },
    { id: "2", name: "Degree_Certificate.pdf", category: "Education", size: "2.4 MB", uploadDate: "10 Jan 2026", status: "Verified", version: "v2.1" },
    { id: "3", name: "Passport_Copy.pdf", category: "Identity", size: "3.1 MB", uploadDate: "05 Jan 2026", status: "Expiring Soon", expiryDate: "20 Mar 2026", version: "v1.0" },
    { id: "4", name: "Offer_Letter.pdf", category: "Company", size: "850 KB", uploadDate: "01 Jan 2026", status: "Verified", version: "v1.1" },
];

export default function EmployeeDocumentHub() {
    const [docs, setDocs] = useState<DocumentItem[]>(initialDocs);
    const [search, setSearch] = useState("");
    const [activeTab, setActiveTab] = useState<string>("All");
    const [selectedDocs, setSelectedDocs] = useState<string[]>([]);

    const filteredDocs = useMemo(() => {
        return docs.filter(doc => {
            const matchesSearch = doc.name.toLowerCase().includes(search.toLowerCase());
            const matchesTab = activeTab === "All" || doc.category === activeTab;
            return matchesSearch && matchesTab;
        });
    }, [search, activeTab, docs]);

    const toggleSelect = (id: string) => {
        setSelectedDocs(prev => prev.includes(id) ? prev.filter(i => i !== id) : [...prev, id]);
    };

    return (
        <div className="p-6 space-y-8 bg-[#F8F9FB] dark:bg-[#06080F] min-h-screen">
            <PageBreadcrumb pageTitle="Employee Document Vault" />

            {/* 1. COMPLIANCE OVERVIEW HUD */}
            <div className="flex flex-col lg:flex-row gap-6">
                <div className="flex-1 grid grid-cols-2 md:grid-cols-4 gap-4">
                    <DocStatCard icon={<FileText />} label="Vault Items" value={docs.length.toString()} color="brand" />
                    <DocStatCard icon={<ShieldCheck />} label="Compliance" value="92%" color="emerald" />
                    <DocStatCard icon={<History />} label="Audit Logs" value="124" color="blue" />
                    <DocStatCard icon={<AlertCircle />} label="Issues" value="1" color="red" />
                </div>
            </div>

            {/* 2. ADVANCED CONTROL BAR */}
            <div className="bg-white dark:bg-gray-900 rounded-[2rem] p-4 shadow-sm border border-gray-100 dark:border-gray-800 flex flex-col md:flex-row justify-between items-center gap-4">
                <div className="flex items-center gap-2">
                    {["All", "Identity", "Education", "Company", "Tax"].map((tab) => (
                        <button
                            key={tab}
                            onClick={() => setActiveTab(tab)}
                            className={`px-5 py-2 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${
                                activeTab === tab 
                                ? "bg-brand-500 text-white shadow-xl shadow-brand-500/20" 
                                : "text-gray-400 hover:text-gray-900 dark:hover:text-white"
                            }`}
                        >
                            {tab}
                        </button>
                    ))}
                </div>

                <div className="flex items-center gap-3 w-full md:w-auto">
                    <div className="relative group">
                        <Search className="absolute left-3 top-2.5 text-gray-400 w-4 h-4" />
                        <input
                            placeholder="Search Vault..."
                            className="pl-10 w-full md:w-64 bg-gray-50 dark:bg-gray-800 border-none rounded-xl px-4 py-2.5 text-xs font-bold outline-none focus:ring-2 focus:ring-brand-500/50 transition-all"
                            value={search}
                            onChange={(e) => setSearch(e.target.value)}
                        />
                    </div>
                    <button className="bg-gray-900 dark:bg-brand-600 text-white p-2.5 rounded-xl shadow-lg hover:scale-105 transition-transform">
                        <Plus size={20} />
                    </button>
                </div>
            </div>

            {/* 3. BULK ACTION HEADER (Appears when items are selected) */}
            {selectedDocs.length > 0 && (
                <div className="bg-brand-600 text-white px-8 py-3 rounded-2xl flex justify-between items-center animate-in slide-in-from-top-4">
                    <span className="text-sm font-bold">{selectedDocs.length} items selected</span>
                    <div className="flex gap-4">
                        <button className="text-xs font-black uppercase tracking-widest flex items-center gap-2 bg-white/10 px-4 py-2 rounded-lg hover:bg-white/20">
                            <Download size={14}/> Download Zip
                        </button>
                        <button className="text-xs font-black uppercase tracking-widest flex items-center gap-2 bg-red-500/20 px-4 py-2 rounded-lg hover:bg-red-500">
                            <Trash2 size={14}/> Delete Bulk
                        </button>
                    </div>
                </div>
            )}

            {/* 4. THE VAULT TABLE */}
            <div className="bg-white dark:bg-gray-900 rounded-[2.5rem] shadow-2xl shadow-gray-200/50 dark:shadow-none border border-gray-100 dark:border-gray-800 overflow-hidden">
                <table className="w-full text-left border-collapse">
                    <thead>
                        <tr className="bg-gray-50/50 dark:bg-gray-800/50 text-[10px] uppercase font-black tracking-[0.2em] text-gray-400">
                            <th className="px-8 py-5 w-10">
                                <input type="checkbox" className="rounded border-gray-300 text-brand-600 focus:ring-brand-500" />
                            </th>
                            <th className="px-6 py-5">Document</th>
                            <th className="px-6 py-5">Verification</th>
                            <th className="px-6 py-5 text-center">Version</th>
                            <th className="px-6 py-5">Timestamp</th>
                            <th className="px-6 py-5 text-right">Ops</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-gray-50 dark:divide-gray-800">
                        {filteredDocs.map((doc) => (
                            <tr key={doc.id} className={`group hover:bg-brand-50/30 dark:hover:bg-brand-500/5 transition-all ${selectedDocs.includes(doc.id) ? 'bg-brand-50/50 dark:bg-brand-500/10' : ''}`}>
                                <td className="px-8 py-4 text-center">
                                    <input 
                                        type="checkbox" 
                                        checked={selectedDocs.includes(doc.id)}
                                        onChange={() => toggleSelect(doc.id)}
                                        className="rounded border-gray-300 text-brand-600 focus:ring-brand-500" 
                                    />
                                </td>
                                <td className="px-6 py-4">
                                    <div className="flex items-center gap-4">
                                        <div className="w-12 h-12 bg-white dark:bg-gray-800 border dark:border-gray-700 rounded-2xl flex items-center justify-center text-brand-600 shadow-sm group-hover:scale-110 transition-transform">
                                            <FileText size={22} />
                                        </div>
                                        <div>
                                            <p className="text-sm font-black text-gray-900 dark:text-white tracking-tight">{doc.name}</p>
                                            <p className="text-[10px] font-bold text-gray-400 uppercase tracking-tighter">{doc.category} • {doc.size}</p>
                                        </div>
                                    </div>
                                </td>
                                <td className="px-6 py-4">
                                    <StatusBadge status={doc.status} />
                                    {doc.expiryDate && <p className="text-[9px] text-red-500 font-bold mt-1 uppercase tracking-tighter">Expires: {doc.expiryDate}</p>}
                                </td>
                                <td className="px-6 py-4 text-center">
                                    <span className="text-[10px] font-mono font-bold bg-gray-100 dark:bg-gray-800 px-2 py-1 rounded text-gray-500">{doc.version}</span>
                                </td>
                                <td className="px-6 py-4">
                                    <div className="flex flex-col">
                                        <span className="text-xs font-bold text-gray-700 dark:text-gray-300">{doc.uploadDate}</span>
                                        <span className="text-[10px] text-gray-400 font-medium">Synced via Cloud</span>
                                    </div>
                                </td>
                                <td className="px-6 py-4 text-right">
                                    <div className="flex justify-end gap-1">
                                        <button className="p-2 text-gray-400 hover:text-brand-600 hover:bg-white dark:hover:bg-gray-800 rounded-xl transition-all"><Eye size={18}/></button>
                                        <button className="p-2 text-gray-400 hover:text-brand-600 hover:bg-white dark:hover:bg-gray-800 rounded-xl transition-all"><Download size={18}/></button>
                                        <button className="p-2 text-gray-400 hover:text-red-500 hover:bg-white dark:hover:bg-gray-800 rounded-xl transition-all"><Trash2 size={18}/></button>
                                    </div>
                                </td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>
        </div>
    );
}

/* --- REUSABLE REFINED COMPONENTS --- */

const DocStatCard = ({ icon, label, value, color }: any) => (
    <div className="bg-white dark:bg-gray-900 p-6 rounded-[2.5rem] border border-gray-100 dark:border-gray-800 shadow-sm hover:shadow-xl transition-all group">
        <div className={`w-12 h-12 rounded-2xl bg-${color}-50 dark:bg-${color}-500/10 flex items-center justify-center text-${color}-600 mb-4 transition-transform group-hover:rotate-12`}>
            {icon}
        </div>
        <p className="text-[10px] font-black text-gray-400 uppercase tracking-[0.2em]">{label}</p>
        <h3 className="text-3xl font-black text-gray-900 dark:text-white mt-1 tracking-tighter">{value}</h3>
    </div>
);

const StatusBadge = ({ status }: { status: DocStatus }) => {
    const variants = {
        Verified: "bg-emerald-50 text-emerald-600 border-emerald-100",
        Pending: "bg-amber-50 text-amber-600 border-amber-100",
        Rejected: "bg-red-50 text-red-600 border-red-100",
        "Expiring Soon": "bg-red-50 text-red-600 border-red-100 animate-pulse",
    };
    return (
        <span className={`px-3 py-1 rounded-full text-[9px] font-black uppercase tracking-widest border ${variants[status]}`}>
            {status}
        </span>
    );
};